template.value:
async $NAME$() {
  await LightningAlert.open({
    message: "$MESSAGE$",
    variant: "$VARIANT$", // if headerless, theme not applicable
    theme: "$THEME$", 
    label: "$LABEL$", // this is the header text
  });
  //Alert has been closed
  $END$
}

async $NAME$() {
  const result = await LightningConfirm.open({
    message: "$MESSAGE$",
    variant: "$VARIANT$", // if headerless, theme not applicable
    theme: "$THEME$", 
    label: "$LABEL$",
  });
  //Confirm has been closed
  //result is true if OK was clicked
  //and false if cancel was clicked
}

const $NAME$ = new CustomEvent("$EVENT_NAME$", {
    detail: {$END$}
});
this.dispatchEvent($NAME$);

gql`
  query $NAME$ {
    uiapi {
      query {
        $TYPE$ {
          edges {
            node {
              Name {
                value
              }
              $END$
            }
          }
        }
      }
    }
  }`

@wire(graphql, {
  query: gql`
    query $NAME$ {
      uiapi {
        aggregate {
          $TYPE$(groupBy: { $GROUPBY$: {group: true} } ) {
            edges {
              node {
                aggregate {
                  $FIELD_NAME$ {
                    avg {
                      displayValue
                    }
                    sum {
                      displayValue
                    }
                  $END$
                  }
                }
              }
            }
            totalCount
          }
        }
      }
    }
  `,
})
$PROPERTY_NAME$;

results;
errors;

@wire(graphql, {
  query: gql`
    query $NAME$ {
      uiapi {
        query {
          $TYPE$ {
            edges {
              node {
                Name {
                  value
                }
                $END$
              }
            }
          }
        }
      }
    }`,
})
$FUNCTION_NAME$({ data, errors }) {
  if (data) {
    this.results = data.uiapi.query.$TYPE$.edges.map((edge) => edge.node);
  }
  this.errors = errors;
}

@wire(graphql, {
  query: gql`
    query $NAME$ {
      uiapi {
        query {
          $TYPE1$(first: 5) {
            edges {
              node {
                Id
                Name {
                  value
                }
              }
            }
          }
          $TYPE2$(first: 5) {
            edges {
              node {
                Id
                $END$
              }
            }
          }
        }
      }
    }
  `
})
$PROPERTY_NAME$;

after;
pageNumber = 1;
pageSize = 5;

@wire(graphql, {
  query: gql`
   query $NAME$($after: String, $pageSize: Int!) {
     uiapi {
       query {
         $TYPE$ (first: $pageSize, after: $after) {
           edges {
             node {
               Id
               $END$
             }
           }
           totalCount
           pageInfo {
             endCursor
             hasNextPage
             hasPreviousPage
           }
         }
       }
     }
   }`,
  variables: "$variables",
})
$PROPERTY_NAME$;

get variables() {
  return {
    after: this.after || null,
    pageSize: this.pageSize || null,
  };
}

@wire(graphql, {
  query: gql`
    query $NAME$ {
      uiapi {
        query {
          $TYPE$ {
            edges {
              node {
                Name {
                  value
                }
                $END$
              }
            }
          }
        }
      }
    }`,
})
$PROPERTY_NAME$;

recordId;

@wire(graphql, {
  query: gql`
    query $NAME$($recordId: ID) {
      uiapi {
        query {
          $TYPE$(where: { Id: { eq: $recordId } }) {
            edges {
              node {
                Id
                Name {
                  value
                }
                $END$
              }
            }
          }
        }
      }
    }
  `,
  variables: "$variables", // Use a getter function to make the variables reactive
})
graphqlQueryResult({ data, errors }) {
  if (data) {
    this.records = data.uiapi.query.$TYPE$.edges.map((edge) => edge.node);
  }
  this.errors = errors;
}

get variables() {
  return {
    recordId: this.recordId,
  };
}

