  type: "standard__objectPage",
  attributes: {
    actionName: "$ACTIONNAME$",
    objectApiName: "$OBJECTAPINAME$"
  }
});

const defaultValues = encodeDefaultFieldValues({
  FirstName: "Fluffy",
  LastName: "McKittens",
  LeadSource: "Other"
  $END$
});

this[NavigationMixin.Navigate]({
    type: "standard__objectPage",
